package io.knowledgebrain.gateway;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.util.*;
class SubmissionFilesProxyTest {
 @Test void bothNewIntentCommandsForwardTheExactKeyWithoutCallerAuthority()throws Exception{for(String suffix:List.of("/submission-files","/submissions/with-files")){var f=new GroupProxyTest();f.init();String root="/api/groups/"+f.id+"/studies/"+f.id+"/assignments/"+f.id+suffix;var request=f.request("POST",root);request.addHeader("Idempotency-Key","a".repeat(32));request.addHeader("If-Match","\"su0\"");request.addHeader("Authorization","Bearer spoof");request.addHeader("X-Principal-Id",f.id);request.setContent("{}".getBytes());f.proxy.proxy(request);verify(f.transport).send(eq(new GatewayRoute("collaboration",root)),eq("POST"),argThat(h->h.get("Idempotency-Key").equals(List.of("a".repeat(32)))&&h.get("If-Match").equals(List.of("\"su0\""))&&!h.containsKey("Authorization")&&!h.containsKey("X-Principal-Id")),eq(request.getContentAsByteArray()));}}
 @Test void missingDuplicateAndMalformedKeysFailBeforeTransport()throws Exception{for(String suffix:List.of("/submission-files","/submissions/with-files")){var f=new GroupProxyTest();f.init();String root="/api/groups/"+f.id+"/studies/"+f.id+"/assignments/"+f.id+suffix;var missing=f.request("POST",root);var malformed=f.request("POST",root);malformed.addHeader("Idempotency-Key","wrong");var duplicate=f.request("POST",root);duplicate.addHeader("Idempotency-Key","a".repeat(32));duplicate.addHeader("Idempotency-Key","a".repeat(32));for(var request:List.of(missing,malformed,duplicate))assertThrows(org.springframework.web.server.ResponseStatusException.class,()->f.proxy.proxy(request));verifyNoInteractions(f.transport);}}
 @Test void completionAndDownloadDoNotRequireAnAllocationKey()throws Exception{var f=new GroupProxyTest();f.init();String base="/api/groups/"+f.id+"/studies/"+f.id+"/assignments/"+f.id;for(String suffix:List.of("/submission-files/"+f.id+"/complete","/submissions/"+f.id+"/revisions/1/files/"+f.id+"/download")){var request=f.request("POST",base+suffix);request.setContent("{}".getBytes());assertEquals(200,f.proxy.proxy(request).getStatusCode().value());}}
}
